/* ═══════════ QUERY HELPERS ═══════════ */
/* Templates call these. They never reach into the arrays directly, so a
   database swap changes this block only.                                  */

const sourceUsedByObligations = id => OBLIGATIONS.filter(o => (o.evidence_sources||[]).indexOf(id) > -1);
const bySourceId  = id => SOURCES.find(s => s.source_id === id);
const byArticleId = id => ARTICLES.find(a => a.article_id === id);
const byPillar    = slug => PILLARS.find(p => p.slug === slug);
const byJurisdiction = slug => JURISDICTIONS.find(j => j.slug === slug);
const byAuthor    = slug => AUTHORS[slug];

const articlesByPillar = slug => ARTICLES.filter(a => a.pillar === slug);
const cornerstoneByPillar = slug => ARTICLES.filter(a => a.pillar === slug && a.cornerstone === true);
const articlesByAuthor = slug => ARTICLES.filter(a => a.author === slug);
const articlesBySource = id => ARTICLES.filter(a => (a.sources||[]).indexOf(id) > -1);
const sourcesForArticle = a => (a.sources||[]).map(bySourceId).filter(Boolean);
const sourcesByAuthority = (list, level) => list.filter(s => s.authority_level === level);
const calendarByJurisdiction = j => j==='all' ? CALENDAR : CALENDAR.filter(e => e.jurisdiction === j);
const intelligenceForArticle = id => INTELLIGENCE.filter(r => (r.articles_affected||[]).indexOf(id) > -1);

/* Real counts only — computed, never typed (§33) */
const counts = {
  articles:        () => ARTICLES.length,
  articlesInPillar:slug => articlesByPillar(slug).length,
  sources:         () => SOURCES.length,
  primarySources:  () => SOURCES.filter(s => s.authority_level === 'primary').length,
  jurisdictions:   () => JURISDICTIONS.length,
  authoredBy:      slug => articlesByAuthor(slug).length,
  reviewedBy:      slug => ARTICLES.filter(a => a.reviewer === slug).length,
  calendarEvents:  () => CALENDAR.length,
  intelligence:    () => INTELLIGENCE.length,
  lastReviewFor:   slug => articlesByAuthor(slug).map(a=>a.last_reviewed).filter(Boolean).sort().pop() || '—'
};

/* Formatting */
const fmtDate = iso => {
  if (!iso) return '—';
  const M = ['January','February','March','April','May','June','July','August','September','October','November','December'];
  const [y,m,d] = iso.split('-');
  return Number(d) + ' ' + M[Number(m)-1] + ' ' + y;
};
const fmtShort = iso => {
  if (!iso) return '—';
  const M = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  const [y,m,d] = iso.split('-');
  return Number(d) + ' ' + M[Number(m)-1] + ' ' + y;
};

